        Row("parking", "What a parking stay costs, and free parking", "Money and health", "both", "Command-Only (Runs When You Ask — No Switch Needed)", "Ask \"how much is parking at ...\" or \"free parking near ...\". \"Parking for my next event\" prices the parking around the next calendar event that has a place; it never adds or edits an event.", "turn on What a parking stay costs, and free parking", "turn on What a parking stay costs, and free parking", "desktop Settings: All features and abilities; phone: All features and abilities", listOf(), listOf(), false, "", "", "not-a-setting", false),
        Row("price-radar", "Flight prices and a price history", "Money and health", "both", "Command-Only (Runs When You Ask — No Switch Needed)", "Ask in chat - \"how much is a flight from Seattle to Tokyo in March?\", \"is the price radar on?\", \"what is the price radar?\". It is off by default; turning it on is the settings file's own line, [price_radar] enabled = true in jarvis-framework.toml - there is no in-app switch and no chat approval card for that switch yet.", "turn on Do arithmetic", "turn on Do arithmetic", "desktop Settings: All features and abilities; phone: All features and abilities", listOf(), listOf(), false, "", "", "not-a-setting", false),
        Row("habit-checkins", "Habit check-ins", "Money and health", "both", "Command-Only (Runs When You Ask — No Switch Needed)", "Backend only today: GET/POST /api/habits and POST /api/habits/<id>/tick, .../untick and .../stop in backend/jarvis_habits.py, installed by the drop-in folder plugins/ready/habits. Neither app has a screen for it yet - the Habits section on the Reminders screen is the next lane.", "turn on Habit check-ins", "turn on Habit check-ins", "desktop Settings: All features and abilities; phone: All features and abilities", listOf(), listOf(), false, "", "", "not-a-setting", false),
